/**
 * Auto-poke script for Facebook (US).
 *
 * Clicks every "poke back" link currently displayed on
 * https://www.facebook.com/pokes/?notif_t=poke, then repeats every second.
 *
 * For other versions, change POKE_BACK_LABEL to the label used in your version.
 */

/** Label of the "poke back" action for the current page locale. */
const POKE_BACK_LABEL = "Balas Colek";

/** Delay between two sweeps of the page, in milliseconds. */
const POKE_INTERVAL_MS = 1000;

/**
 * Click every "poke back" link currently displayed, then schedule the next run.
 *
 * @returns {void}
 */
function poke() {
    const spans = document.getElementsByTagName("span");

    for (let i = 0; i < spans.length; i++) {
        const span = spans[i];

        if (span.innerHTML.includes(POKE_BACK_LABEL)) {
            span.click();
        }
    }

    setTimeout(poke, POKE_INTERVAL_MS);
}

poke();
